SELECT (MOD(MINUTE(candle_open_time)+1,5)=0) AS at_5m_boundary, COUNT(*) AS n, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, candle_open_time + INTERVAL 1 MINUTE, generated_at))/1e6,3) AS avg_s, ROUND(MAX(TIMESTAMPDIFF(MICROSECOND, candle_open_time + INTERVAL 1 MINUTE, generated_at))/1e6,3) AS max_s FROM trade_signal WHERE interval_code = '1m' AND candle_open_time >= '2026-10-11 00:00:00' AND candle_open_time < '2026-10-12 18:00:00' GROUP BY at_5m_boundary